CREATE OR REPLACE FUNCTION public.publish_planning_to_lab(p_planning_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pl public.production_planning%ROWTYPE;
  v_result jsonb;
  v_count int;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO v_pl FROM public.production_planning WHERE id = p_planning_id FOR UPDATE;
  IF v_pl.id IS NULL THEN RAISE EXCEPTION 'planning_not_found'; END IF;

  IF v_pl.status IN ('em_producao','produzido','entregue') THEN
    RAISE EXCEPTION 'already_published';
  END IF;

  IF v_pl.planned_start_date IS NOT NULL AND v_pl.planned_finish_date IS NOT NULL
     AND v_pl.planned_finish_date < v_pl.planned_start_date THEN
    RAISE EXCEPTION 'invalid_dates';
  END IF;

  PERFORM public._validate_planning_integrity(v_pl.partner_order_id);

  v_result := public.generate_production_orders_from_partner(v_pl.partner_order_id);
  v_count := COALESCE((v_result->>'os_created')::int, 0);

  IF v_count = 0 AND NOT EXISTS (
    SELECT 1 FROM public.production_order_link WHERE planning_id = v_pl.id
  ) THEN
    RAISE EXCEPTION 'LAB_NO_MANUFACTURABLE_ITEMS' USING ERRCODE='23514', HINT='Químicos e fertilizantes permanecem no catálogo e nas solicitações, sem fabricação.';
  END IF;

  INSERT INTO public.laboratorio_esteira_eventos (os_id, origem_os, acao, etapa_nova, usuario_id, observacao)
  SELECT os.id, COALESCE(os.origem,'b2b'), 'demanda_publicada', 'recebido_no_lab', v_uid,
         'Planejamento publicado no Cockpit'
  FROM public.ordens_servico os
  WHERE os.partner_order_id = v_pl.partner_order_id
    AND platform_private.lab_item_is_manufacturable(os.produto_id,os.microrganismo_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.laboratorio_esteira_eventos e
      WHERE e.os_id = os.id AND e.acao = 'demanda_publicada'
    );

  -- Advance OS status aprovada -> programada so the treadmill transitions are valid.
  UPDATE public.ordens_servico
     SET status = 'programada'
   WHERE partner_order_id = v_pl.partner_order_id
     AND status::text = 'aprovada'
     AND platform_private.lab_item_is_manufacturable(produto_id,microrganismo_id);

  UPDATE public.production_planning
     SET status = 'planejado', updated_at = now()
   WHERE id = v_pl.id AND status IN ('aguardando_planejamento','replanejar');

  INSERT INTO public.production_timeline_events (partner_order_id, event_type, actor_id, meta)
  VALUES (v_pl.partner_order_id, 'planejamento_publicado', v_uid,
          jsonb_build_object('planning_id', v_pl.id, 'os_created', v_count));

  INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_pl.partner_order_id, v_pl.partner_id, v_uid, 'planejamento_publicado',
          jsonb_build_object('planning_id', v_pl.id, 'os_created', v_count));

  PERFORM public.refresh_esteira_laboratorio();

  RETURN jsonb_build_object('ok', true, 'planning_id', v_pl.id, 'os_created', v_count,'non_lab_items',v_result->'non_lab_items');
END
$function$

CREATE OR REPLACE FUNCTION public.reservar_estoque_item(p_item_id uuid, p_qty numeric, p_os_id uuid, p_os_tipo text, p_cliente_id uuid DEFAULT NULL::uuid, p_partner_id uuid DEFAULT NULL::uuid, p_partner_order_id uuid DEFAULT NULL::uuid, p_observacao text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.estoque_produto%ROWTYPE;
  v_volume_reservado numeric;
  v_new_id uuid;
  v_parent_ctx jsonb;
BEGIN
  PERFORM platform_private.stock_motor_actor('reserva');
  IF p_qty IS NULL OR p_qty::text IN ('NaN','Infinity','-Infinity') OR p_qty <= 0 THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF auth.uid() IS NULL OR NOT public.fn_estoque_pode_operar(auth.uid(), 'reserva') THEN
    RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO: perfil sem permissão para reservar estoque'
      USING ERRCODE = '42501';
  END IF;

  SELECT c.ctx INTO v_parent_ctx FROM platform_private.stock_motor_context c WHERE c.txid=txid_current() AND c.actor=auth.uid() AND c.item=p_item_id;
  IF v_parent_ctx IS NOT NULL AND (v_parent_ctx->>'acao' IS DISTINCT FROM 'reserva' OR v_parent_ctx->'reserve_args' IS DISTINCT FROM jsonb_strip_nulls(jsonb_build_object('os_id',p_os_id::text,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id::text,'partner_id',p_partner_id::text,'partner_order_id',p_partner_order_id::text,'observacao',p_observacao))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF v_parent_ctx IS NULL THEN
   v_parent_ctx:=jsonb_build_object('acao','reserva','origem','reservar_estoque_item','usuario_id',auth.uid()::text,'metadata',jsonb_build_object('stock_request_item',p_item_id::text,'stock_request_actor',auth.uid()::text));
  END IF;
  PERFORM public.fn_estoque_ctx_force(v_parent_ctx);
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'Quantidade a reservar deve ser maior que zero.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_os_id IS NULL THEN
    RAISE EXCEPTION 'Reserva requer uma OS vinculada.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_item
  FROM public.estoque_produto
  WHERE id = p_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item de estoque % não encontrado.', p_item_id
      USING ERRCODE = 'no_data_found';
  END IF;

  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF v_item.status::text <> 'disponivel' THEN
    RAISE EXCEPTION 'Item % não está disponível para reserva (status: %).', p_item_id, v_item.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_qty > COALESCE(v_item.quantidade, 0) THEN
    RAISE EXCEPTION 'Quantidade solicitada (%) excede o disponível (%) para esta embalagem.',
      p_qty, COALESCE(v_item.quantidade, 0)
      USING ERRCODE = 'check_violation';
  END IF;

  v_volume_reservado := CASE
    WHEN COALESCE(v_item.volume_total, 0) > 0 AND COALESCE(v_item.quantidade, 0) > 0
      THEN (p_qty * v_item.volume_total) / v_item.quantidade
    ELSE NULL
  END;

  IF p_qty = v_item.quantidade THEN
    UPDATE public.estoque_produto SET
      status = 'reservado',
      reservado_para_os_id = p_os_id,
      reservado_para_os_tipo = p_os_tipo,
      reservado_para_cliente_id = CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      reservado_para_partner_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      reservado_para_partner_order_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      quantidade_reservada = p_qty,
      observacao_reserva = p_observacao
    WHERE id = p_item_id;
    v_new_id := p_item_id;
  ELSE
    INSERT INTO public.estoque_produto (
      produto_id, lote_id, microrganismo_id, envase_id,
      quantidade, volume_total, validade, status,
      reservado_para_os_id, reservado_para_os_tipo,
      reservado_para_cliente_id, reservado_para_partner_id, reservado_para_partner_order_id,
      quantidade_reservada, observacao_reserva
    ) VALUES (
      v_item.produto_id, v_item.lote_id, v_item.microrganismo_id, v_item.envase_id,
      p_qty, v_volume_reservado, v_item.validade, 'reservado',
      p_os_id, p_os_tipo,
      CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      p_qty, p_observacao
    ) RETURNING id INTO v_new_id;

    UPDATE public.estoque_produto SET
      quantidade = v_item.quantidade - p_qty,
      volume_total = CASE
        WHEN COALESCE(v_item.volume_total, 0) > 0 THEN v_item.volume_total - v_volume_reservado
        ELSE volume_total
      END
    WHERE id = p_item_id;
  END IF;

  PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close();
  RETURN v_new_id;
EXCEPTION WHEN OTHERS THEN PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close(); RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_criar_embalagens_pos_envase(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_qtd int := COALESCE((p_payload->>'quantidade_embalagens')::int, 0);
  v_lote uuid := (p_payload->>'lote_id')::uuid;
  v_volume numeric := (p_payload->>'volume')::numeric;
  v_unidade text := COALESCE(p_payload->>'unidade','L');
  v_gerar_et bool := COALESCE((p_payload->>'gerar_etiqueta_automaticamente')::bool, false);
  v_envase uuid := NULLIF(p_payload->>'envase_id','')::uuid;
  v_produto uuid := NULLIF(p_payload->>'produto_id','')::uuid;
  v_cliente uuid := NULLIF(p_payload->>'cliente_id','')::uuid;
  v_fazenda uuid := NULLIF(p_payload->>'fazenda_id','')::uuid;
  v_fab date; v_val date;
  v_codigo text; v_emb_id uuid; v_etq_id uuid;
  v_arr jsonb := '[]'::jsonb;
  v_meta jsonb;
  v_produto_warning bool := false;
  v_warnings jsonb := '[]'::jsonb;
  i int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(gen_random_uuid()) THEN
    RAISE EXCEPTION 'sem permissão';
  END IF;
  IF v_lote IS NULL THEN RAISE EXCEPTION 'lote_id obrigatório'; END IF;
  IF v_volume IS NULL OR v_volume <= 0 THEN RAISE EXCEPTION 'volume inválido'; END IF;
  IF v_qtd < 1 OR v_qtd > 500 THEN RAISE EXCEPTION 'quantidade entre 1 e 500'; END IF;

  -- Valida referências reais (Fase 2.2)
  IF NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote) THEN
    RAISE EXCEPTION 'Lote informado não existe (%).', v_lote;
  END IF;
  IF v_envase IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.envase WHERE id = v_envase) THEN
    RAISE EXCEPTION 'Envase informado não existe (%).', v_envase;
  END IF;
  IF v_cliente IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = v_cliente) THEN
    RAISE EXCEPTION 'Cliente informado não existe (%).', v_cliente;
  END IF;
  IF v_fazenda IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.fazendas WHERE id = v_fazenda) THEN
    RAISE EXCEPTION 'Fazenda informada não existe (%).', v_fazenda;
  END IF;

  -- Fallback de produto_id a partir do lote
  IF v_produto IS NULL THEN
    SELECT produto_id INTO v_produto FROM public.lotes WHERE id = v_lote;
  END IF;
  IF v_produto IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.produtos WHERE id = v_produto) THEN
    RAISE EXCEPTION 'Produto informado não existe (%).', v_produto;
  END IF;
  IF v_produto IS NULL THEN
    v_produto_warning := true;
    v_warnings := v_warnings || to_jsonb('produto_id_nao_identificado'::text);
  END IF;

  SELECT data_envase INTO v_fab FROM public.envase WHERE id = v_envase;
  IF v_fab IS NULL THEN v_fab := CURRENT_DATE; END IF;
  v_val := v_fab + INTERVAL '6 months';

  FOR i IN 1..v_qtd LOOP
    v_codigo := 'AR-EMB-' || lpad(nextval('public.estoque_embalagem_seq')::text, 6, '0');
    v_meta := jsonb_build_object();
    IF v_produto_warning THEN
      v_meta := v_meta || jsonb_build_object('produto_id_nao_identificado', true);
    END IF;

    INSERT INTO public.estoque_embalagens(
      codigo_embalagem, lote_id, produto_id, envase_id, envase_item_id, volume, unidade, quantidade,
      tipo_embalagem, local_estoque, cliente_id, fazenda_id, fabricado_em, validade_em,
      entrada_estoque_em, criado_por, metadata
    ) VALUES (
      v_codigo, v_lote, v_produto, v_envase,
      NULLIF(p_payload->>'envase_item_id','')::uuid,
      v_volume, v_unidade, 1,
      p_payload->>'tipo_embalagem',
      p_payload->>'local_estoque',
      v_cliente, v_fazenda,
      v_fab, v_val,
      now(), v_uid, v_meta
    ) RETURNING id INTO v_emb_id;

    INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_novo, user_id, metadata)
      VALUES (v_emb_id, 'entrada_estoque', 'em_estoque', v_uid, jsonb_build_object('codigo', v_codigo));

    v_etq_id := NULL;
    IF v_gerar_et THEN
      SELECT (public.rpc_gerar_etiqueta_produto(jsonb_build_object(
        'lote_id', v_lote, 'envase_id', v_envase,
        'produto_id', v_produto,
        'cliente_id', v_cliente,
        'fazenda_id', v_fazenda,
        'volume', v_volume, 'unidade', v_unidade,
        'quantidade_embalagens', 1
      )) ->> 'etiqueta_id')::uuid INTO v_etq_id;

      IF v_etq_id IS NULL THEN
        RAISE EXCEPTION 'Falha ao gerar etiqueta automática para a embalagem. Nenhuma embalagem foi criada. Tente novamente ou gere as embalagens sem etiqueta automática.';
      END IF;

      UPDATE public.estoque_embalagens SET etiqueta_id = v_etq_id WHERE id = v_emb_id;
      UPDATE public.produto_etiquetas SET embalagem_id = v_emb_id WHERE id = v_etq_id;
      INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, user_id, metadata)
        VALUES (v_emb_id, 'etiqueta_vinculada', v_uid, jsonb_build_object('etiqueta_id', v_etq_id));
      INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, metadata)
        VALUES (v_etq_id, 'etiqueta_gerada', v_uid, jsonb_build_object('embalagem_id', v_emb_id));
    END IF;

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
      VALUES ('estoque_embalagem', v_emb_id, 'EMB_CREATED', v_uid,
              jsonb_build_object('codigo', v_codigo, 'etiqueta_id', v_etq_id, 'produto_id', v_produto));

    v_arr := v_arr || jsonb_build_object('embalagem_id', v_emb_id, 'codigo_embalagem', v_codigo, 'etiqueta_id', v_etq_id);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_embalagens', v_qtd,
    'embalagens', v_arr,
    'warnings', v_warnings
  );
END $function$

CREATE OR REPLACE FUNCTION public.rpc_planejamento_publicar_v1(p_planning_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_pl public.production_planning%ROWTYPE;
 v_prev public.production_planning_publications%ROWTYPE; v_result jsonb; v_count int;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'nao_autenticado' USING ERRCODE='42501'; END IF;
 IF NOT(public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN RAISE EXCEPTION 'permissao_negada' USING ERRCODE='42501'; END IF;
 IF p_planning_id IS NULL THEN RAISE EXCEPTION 'planejamento_invalido' USING ERRCODE='22023'; END IF;
 IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key))<8 THEN RAISE EXCEPTION 'chave_idempotencia_obrigatoria' USING ERRCODE='22023'; END IF;
 -- Nunca devolver recibo de origem interna bloqueada, nem em replay.
 -- Escopo antes de status/recibo: ID inexistente e cross-tenant dão a mesma negação.
 IF public.h15_actor_organization() IS NULL THEN RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT pl.* INTO v_pl FROM public.production_planning pl
 WHERE pl.id=p_planning_id AND platform_private.lab_partner_order_authorized(pl.partner_order_id) FOR UPDATE;
 IF v_pl.id IS NULL THEN RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=v_pl.partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('planejamento_publicar:'||p_planning_id::text));
 SELECT * INTO v_prev FROM public.production_planning_publications WHERE idempotency_key=btrim(p_idempotency_key);
 IF FOUND THEN
  IF v_prev.planning_id<>p_planning_id THEN RAISE EXCEPTION 'chave_idempotencia_conflitante' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('ok',true,'replay',true,'planning_id',v_prev.planning_id,'os_created',v_prev.os_created,'resultado',v_prev.resultado);
 END IF;
 SELECT * INTO v_prev FROM public.production_planning_publications WHERE planning_id=p_planning_id;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'replay',true,'planning_id',v_prev.planning_id,'os_created',v_prev.os_created,'resultado',v_prev.resultado); END IF;
 v_result:=public.publish_planning_to_lab(p_planning_id); v_count:=coalesce((v_result->>'os_created')::int,0);
 INSERT INTO public.production_planning_publications(planning_id,partner_order_id,idempotency_key,os_created,resultado,performed_by)
 VALUES(p_planning_id,v_pl.partner_order_id,btrim(p_idempotency_key),v_count,v_result,v_uid);
 RETURN jsonb_build_object('ok',true,'replay',false,'planning_id',p_planning_id,'os_created',v_count,'resultado',v_result);
END $function$
